mapper.select:
select wtr.*, wsio.order_number as stockInOrderNumber, ww.warehouse_name as warehouseName,
       wco.owner_name as ownerName, wp.product_name as productName
from wms_tasks_records wtr
         left join wms_tasks wt on wtr.task_id = wt.id
         left join wms_stock_in_orders wsio on wtr.stock_in_order_id = wsio.id
         left join wms_warehouses ww on wt.target_warehouse_id = ww.id
         left join wms_products wp on wtr.product_id = wp.id
         left join wms_cargo_owners wco on wp.owner_id = wco.id
where 1=1

    and wtr.task_number = #{taskNumber}


    and wtr.task_type = #{taskType}


    and wtr.operator = #{operator}


    and wtr.stock_in_order_id = #{stockInOrderId}


    and wtr.wave_order_id = #{waveOrderId}


    and wtr.out_order_id = #{outOrderId}

order by wtr.create_time desc
